+        let b = Backoff::new(Duration::from_millis(100), Duration::from_secs(1), 6);
+        let ms: Vec<u128> = b.map(|d| d.as_millis()).collect();
+        assert_eq!(ms, vec![100, 200, 400, 800, 1000, 1000]);
